/**
 * The CodeRouter CLI is a guest convenience, not the machine's auth
 * mechanism. Model requests use the environment generated by agent-config.sh
 * (and, on edge-wired deployments, the Freestyle header injection); installing
 * the CLI merely makes `coderouter`/`cr` available to a person or an agent.
 *
 * Keep the version pinned so an attach-time heal cannot silently change the
 * command's wire contract. The image bake installs the same npm package, while
 * this command repairs machines created from older snapshots.
 */
export const GUEST_CODEROUTER_PACKAGE = "coderouter";
export const GUEST_CODEROUTER_VERSION = "0.3.2";
export const GUEST_CODEROUTER_INSTALL_ROOT = "/usr/local/bin";
export const GUEST_CODEROUTER_BIN_PATH = `${GUEST_CODEROUTER_INSTALL_ROOT}/coderouter`;
export const GUEST_CODEROUTER_ALIAS_PATH = `${GUEST_CODEROUTER_INSTALL_ROOT}/cr`;
export const GUEST_CODEROUTER_MARKER_PATH = "/etc/cmux/coderouter-version";

/**
 * Install the pinned cross-platform npm package and expose both advertised
 * bins in the system PATH. The marker makes the common heal path a cheap
 * no-op; the package and both executable paths are checked before trusting it.
 * Every write is staged and moved into place so a killed exec cannot leave a
 * half-written launcher.
 */
export function guestCoderouterInstallCommand(): string {
  const packageSpec = `${GUEST_CODEROUTER_PACKAGE}@${GUEST_CODEROUTER_VERSION}`;
  const prefix = GUEST_CODEROUTER_BIN_PATH.slice(0, GUEST_CODEROUTER_BIN_PATH.lastIndexOf("/"));
  return [
    `if [ "$(cat ${GUEST_CODEROUTER_MARKER_PATH} 2>/dev/null || true)" = "${GUEST_CODEROUTER_VERSION}" ] && [ -x ${GUEST_CODEROUTER_BIN_PATH} ] && [ -x ${GUEST_CODEROUTER_ALIAS_PATH} ]; then exit 0; fi`,
    "npm_bin=\"$(command -v npm 2>/dev/null || true)\"",
    "[ -n \"$npm_bin\" ] || { echo 'coderouter: npm is required to repair the guest CLI' >&2; exit 127; }",
    `\"$npm_bin\" install --global --foreground-scripts '${packageSpec}'`,
    "npm_prefix=\"$(\"$npm_bin\" prefix --global 2>/dev/null || true)\"",
    "[ -n \"$npm_prefix\" ] || { echo 'coderouter: npm did not report a global prefix' >&2; exit 1; }",
    `mkdir -p ${prefix} ${GUEST_CODEROUTER_MARKER_PATH.slice(0, GUEST_CODEROUTER_MARKER_PATH.lastIndexOf("/"))}`,
    `source_coderouter=\"$npm_prefix/bin/coderouter\"; source_cr=\"$npm_prefix/bin/cr\"`,
    "[ -x \"$source_coderouter\" ] || { echo 'coderouter: global install did not create coderouter' >&2; exit 1; }",
    "[ -x \"$source_cr\" ] || { echo 'coderouter: global install did not create cr alias' >&2; exit 1; }",
    `[ \"$source_coderouter\" = \"${GUEST_CODEROUTER_BIN_PATH}\" ] || ln -sfn \"$source_coderouter\" ${GUEST_CODEROUTER_BIN_PATH}`,
    `[ \"$source_cr\" = \"${GUEST_CODEROUTER_ALIAS_PATH}\" ] || ln -sfn \"$source_cr\" ${GUEST_CODEROUTER_ALIAS_PATH}`,
    `printf '%s\\n' '${GUEST_CODEROUTER_VERSION}' > ${GUEST_CODEROUTER_MARKER_PATH}.tmp && chmod 0644 ${GUEST_CODEROUTER_MARKER_PATH}.tmp && mv ${GUEST_CODEROUTER_MARKER_PATH}.tmp ${GUEST_CODEROUTER_MARKER_PATH}`,
    `test -x ${GUEST_CODEROUTER_BIN_PATH} && test -x ${GUEST_CODEROUTER_ALIAS_PATH}`,
  ].join(" && ");
}
